msgs=c.execute("select id,content from messages where session_id=? and role='user' order by id",(s,)).fetchall()
# parse all demo blocks allowing up to output delimiters
pairs=[]
for mid,txt in msgs:
 for m in re.finditer(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \1 output \(\2x\3\):\n(.*?)(?=\n\nSame instance\.|\nWrong attempts|\n\nFeedback since|$)',txt,re.S):
  di=int(m[1]);a=[list(map(int,x.split())) for x in m[4].splitlines()];b=[list(map(int,x.split())) for x in m[5].splitlines()];dif=[(r,j,a[r][j],b[r][j]) for r in range(len(a)) for j in range(len(a[r])) if a[r][j]!=b[r][j]]
  pairs.append((di,a,b,dif))
print('demos',len(pairs))
for di,a,b,dif in pairs:
 if not dif:continue
 h,w=len(a),len(a[0]); bg=max(collections.Counter(sum(a,[])).items(),key=lambda z:z[1])[0]
 # marker color is dest; find connected component with highest count of dest color? marker's cells unchanged and other changed target only dest in output
 dest=dif[0][3]
 comps=[];seen=set()
 for r in range(h):
  for j in range(w):
   v=a[r][j]
   if (r,j) in seen:continue
   st=[(r,j)];seen.add((r,j));cells=[]
   while st:
    x,y=st.pop();cells.append((x,y))
    for q in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=q[0]<h and 0<=q[1]<w and q not in seen and a[q[0]][q[1]]==v:seen.add(q);st.append(q)
   rs=[x for x,y in cells];cs=[y for x,y in cells]; bb=(min(rs),min(cs),max(rs),max(cs)); comps.append((v,cells,bb))
 tgtcells=[(r,j) for r,j,src,dst in dif]; src=dif[0][2];tgtbb=(min(r for r,j in tgtcells),min(j for r,j in tgtcells),max(r for r,j in tgtcells),max(j for r,j in tgtcells)); tgt=next(x for x in comps if x[0]==src and set(x[1])==set(tgtcells))
 marker=max((x for x in comps if x[0]==dest),key=lambda x:len(x[1]))
 mcell=marker[1]; mr=[r for r,j in mcell];mc=[j for r,j in mcell]; mcenter=(sum(mr)/len(mr),sum(mc)/len(mc)); tcenter=(sum(r for r,j in tgtcells)/len(tgtcells),sum(j for r,j in tgtcells)/len(tgtcells));
 # L elbow at cell with degree 2, get bbox corner intersection
 # report distances from each comp bbox from marker bbox (Chebyshev/Manhattan)
 mb=(min(mr),min(mc),max(mr),max(mc));
 def boxd(bb,bb2):
  dr=max(0,bb[0]-bb2[2]-1,bb2[0]-bb[2]-1);dc=max(0,bb[1]-bb2[3]-1,bb2[1]-bb[3]-1);return dr+dc, max(dr,dc), (dr,dc)
 rank=[]
 for v,cells,bb in comps:
  if set(cells)==set(mcell):continue
  d=boxd(mb,bb)[0]
  rank.append((d,v,len(cells),bb, (sum(r for r,j in cells)/len(cells),sum(j for r,j in cells)/len(cells)), set(cells)==set(tgtcells)))
 rank.sort(key=lambda x:x[0]); print('\nD',di,'dims',h,w,'bg',bg,'dest',dest,'marker n/bb',len(mcell),mb,'center',mcenter,'target',src,len(tgtcells),tgtbb,'center',tcenter,'closest comps',rank[:8])

